          latestThumbUrl,
          handleDragStart,
          setPreviewIndex: lightbox.setPreviewIndex,
          setPreviewCustomItem: lightbox.setPreviewCustomItem,
          resetZoom: lightbox.resetZoom,
          handleForkToWorkbench,
          seedMode,
          seed,
